class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        deque<int> q;                                   // q 存下标，对应的值递减
        vector<int> res;
        for (int i = 0; i < (int)nums.size(); i++) {
            while (!q.empty() && nums[q.back()] <= nums[i]) {
                q.pop_back();                           // 队尾比新数小，没用了
            }
            q.push_back(i);
            if (q.front() <= i - k) {
                q.pop_front();                          // 队头滑出窗口
            }
            if (i >= k - 1) {
                res.push_back(nums[q.front()]);
            }
        }
        return res;
    }
};

