func maxSlidingWindow(nums []int, k int) []int {
	q, res := []int{}, []int{} // q 存下标，对应的值递减
	for i, x := range nums {
		for len(q) > 0 && nums[q[len(q)-1]] <= x {
			q = q[:len(q)-1] // 队尾比新数小，没用了
		}
		q = append(q, i)
		if q[0] <= i-k {
			q = q[1:] // 队头滑出窗口
		}
		if i >= k-1 {
			res = append(res, nums[q[0]])
		}
	}
	return res
}

